import { composerTypedText, fileComposerPart, type ComposerPart } from "@/agent/composerParts";
import { informationComposerParts } from "@/agent/informationComposer";
import { cloneInputParts, inputPartsText, validateInputParts } from "@/agent/shortcutStructure";
import { registerStudioNavigationGuard } from "@/agent/studioNavigation";
import { useInformationFilePicker } from "@/agent/useInformationFilePicker";
import ShortcutEditorDialog from "./ShortcutEditorDialog.vue";
import ShortcutContent from "./ShortcutContent.vue";
import InformationPickerDialog from "./InformationPickerDialog.vue";
import ConfirmDialog from "./ConfirmDialog.vue";

export interface ScheduleAgentOption { id: string; name: string; model?: string }
const props = withDefaults(defineProps<{ modelValue: boolean; item?: ScheduleJob | null; draft?: ScheduleDraft | null; agentId?: string; agentName?: string; sessionId?: string | null; agents?: ScheduleAgentOption[]; models?: ModelInfo[]; serverTimezone?: string; serverTimezoneLabel?: string; draftBusy?: boolean }>(), { item: null, draft: null, agentId: "", agentName: "", sessionId: "", agents: () => [], models: () => [], serverTimezone: "", serverTimezoneLabel: "", draftBusy: false });
const emit = defineEmits<{ "update:modelValue": [boolean]; saved: [job: ScheduleJob]; "request-draft": [] }>();
const { t, locale } = useI18n();
const step = ref<"content" | "timing">("content");
const title = ref(""), targetAgent = ref(""), parts = ref<ComposerPart[]>([]), timing = ref(newScheduleTiming());
const turnLimitMode = ref<"unlimited" | "limited" | "legacy">("unlimited"), maxTurns = ref(300), approvalMode = ref<"auto" | "standard" | "strict">("auto");
const expires = ref(""), neverExpires = ref(false), advanced = ref(false), contentId = ref("");
const nextRuns = ref<string[]>([]), previewLoading = ref(false), previewError = ref(""), previewTimezone = ref(""), previewSignature = ref("");
let previewSequence = 0, previewTimer: ReturnType<typeof setTimeout> | undefined;
const saving = ref(false), error = ref("");
const contentEditor = ref<InstanceType<typeof ShortcutEditorDialog> | null>(null), confirm = ref<InstanceType<typeof ConfirmDialog> | null>(null);
const catalog = ref<ShortcutsView | null>(null), skills = ref<SkillInfo[]>([]), catalogError = ref(""), catalogLoading = ref(false);
let catalogSequence = 0;
const sourceSession = ref("");
let initial = "", epoch = 0, disposed = false, originalExpiry = "", originalExpiryInput = "", originalZone = "", originalAt = "", originalAtInput = "";
const frequencies: ScheduleFrequency[] = ["once", "hourly", "daily", "weekdays", "weekly", "monthly", "interval", "custom"];
const zones = computed(() => [...new Set([timing.value.timezone, browserTimeZone(), props.serverTimezone, "Asia/Shanghai", "UTC", "Asia/Tokyo", "Asia/Singapore", "Europe/London", "Europe/Berlin", "America/New_York", "America/Los_Angeles"].filter(Boolean))]);
const currentAgentName = computed(() => props.item?.agent_name || props.agents.find(agent => agent.id === targetAgent.value)?.name || (targetAgent.value === props.agentId ? props.agentName : "") || targetAgent.value);
const currentModel = computed(() => props.item?.agent_model || props.agents.find(agent => agent.id === targetAgent.value)?.model || "");
const busy = computed(() => saving.value || props.draftBusy);
const wireParts = computed(() => composerInputParts(parts.value, key => { const file = parts.value.find(part => part.type === "file" && part.key === key); if (!file || file.type !== "file" || !file.path || file.status !== "ready") throw new Error(t("scheduleDialog.fileNotReady")); return [file.path]; }));
const state = () => JSON.stringify([title.value, targetAgent.value, parts.value, timing.value, turnLimitMode.value, maxTurns.value, approvalMode.value, expires.value, neverExpires.value]);
const dirty = computed(() => props.modelValue && state() !== initial);
const context = () => JSON.stringify([props.agentId, props.sessionId, props.item?.id, props.draft?.key]);
let openedContext = "";
const validContext = computed(() => openedContext === context() && !!props.agentId && targetAgent.value === props.agentId);
const referenceChoices = computed(() => shortcutEntries(catalog.value));
const contentItem = computed<ShortcutSnapshot>(() => ({ id: contentId.value, title: title.value, content: composerTypedText(parts.value), parts: cloneInputParts(wireParts.value), input_layout: "inline" }));
function message(value: unknown) { const raw = value instanceof Error ? value.message : String(value); return raw.startsWith("scheduleDialog.") ? t(raw) : raw; }
function initialize() {
  epoch++; error.value = ""; saving.value = false; advanced.value = false; step.value = "content"; contentId.value = `schedule_content_${epoch}`;
  const item = props.item, draft = props.draft;
  title.value = item?.title || (item ? item.id : draft?.title || ""); targetAgent.value = item?.agent_id || draft?.agent_id || props.agentId;
  const input = item?.parts?.length ? item.parts : draft?.parts?.length ? draft.parts : [{ type: "text" as const, text: item?.prompt || draft?.prompt || "" }];
  parts.value = informationComposerParts(JSON.parse(JSON.stringify(input)), []); timing.value = item ? timingFromJob(item) : newScheduleTiming();
  turnLimitMode.value = item ? item.turn_limit_mode || "legacy" : "unlimited"; maxTurns.value = item?.max_turns || 300; approvalMode.value = item ? item.approval_mode || "standard" : "auto";
  sourceSession.value = draft?.source_session_id || (targetAgent.value === props.agentId ? props.sessionId || "" : "");
  originalExpiry = item?.expires_at || ""; originalZone = timing.value.timezone;
  const zone = timing.value.timezone || item?.effective_timezone || props.serverTimezone || browserTimeZone(); neverExpires.value = item ? !originalExpiry : false;
  expires.value = localDateTimeInput(originalExpiry || new Date(Date.now() + 30 * 86400000).toISOString(), zone); originalExpiryInput = expires.value; originalAt = item?.at || ""; originalAtInput = timing.value.at;
  openedContext = context(); initial = state();
}
watch(() => [props.modelValue, props.item?.id, props.draft?.key] as const, ([open]) => { if (open) initialize(); else epoch++; }, { immediate: true });
async function loadSources() {
  const ticket = ++catalogSequence, origin = context(); catalog.value = null; skills.value = []; catalogError.value = "";
  if (!props.modelValue || !props.agentId) { catalogLoading.value = false; return; }
  catalogLoading.value = true;
  const sid = sourceSession.value || props.sessionId;
  const results = await Promise.allSettled([shortcutsApi.list(props.agentId), sid ? api.skills(sid) : Promise.resolve({ skills: [] as SkillInfo[] })]);
  if (disposed || ticket !== catalogSequence || origin !== context() || !props.modelValue) return;
  const [shortcuts, catalogSkills] = results;
  if (shortcuts.status === "fulfilled" && shortcuts.value.agent_id === props.agentId) catalog.value = shortcuts.value;
  else catalogError.value = message(shortcuts.status === "rejected" ? shortcuts.reason : new Error(t("shortcuts.scopeChanged")));
  if (catalogSkills.status === "fulfilled") skills.value = catalogSkills.value.skills;
  else catalogError.value ||= message(catalogSkills.reason);
  catalogLoading.value = false;
}
watch(() => [props.modelValue, props.agentId, props.sessionId, props.item?.id, props.draft?.key] as const, () => void loadSources(), { immediate: true });
async function resolveReference(id: string) {
  const item = referenceChoices.value.find(entry => entry.id === id); if (!item) throw new Error(t("shortcuts.itemDeleted"));
  if (item.source !== "starter") return JSON.parse(JSON.stringify(item));
  const sid = sourceSession.value || props.sessionId, origin = context(); if (!sid || !validContext.value) throw new Error(t("nestedShortcuts.sessionRequired"));
  const result = await resolveStarterShortcut(sid, item); if (disposed || origin !== context() || !props.modelValue || step.value !== "content") throw new Error(t("shortcuts.scopeChanged")); return result;
}
const uploadFile = computed(() => (sourceSession.value || props.sessionId) && validContext.value ? async (file: File) => {
  const sid = sourceSession.value || props.sessionId!, origin = context(), ticket = epoch;
  const result = await api.uploadAttachment(sid, file, file.name);
  if (disposed || ticket !== epoch || origin !== context() || !props.modelValue || step.value !== "content") throw new Error(t("shortcuts.scopeChanged")); return result;
} : undefined);
const informationPicker = useInformationFilePicker({ allowedKinds: ["file", "shortcut"], scope: () => JSON.stringify([context(), props.modelValue, step.value, contentId.value]),
  resolve: async entry => { const full = await informationApi.entry(entry.id, entry.version);
    if (full.kind === "file" && full.file) return [fileComposerPart({ key: full.file.asset, path: full.file.asset, label: full.file.name, status: "ready", asFile: true, mime: full.file.mime, size: full.file.size })];
    if (full.kind === "shortcut" && full.shortcut) return informationComposerParts([{ type: "shortcut", shortcut_id: `${full.id}_v${full.version}`, title: full.shortcut.title, text: full.shortcut.content, icon: full.shortcut.icon, language: full.shortcut.language, ...(full.shortcut.parts ? { parts: cloneInputParts(full.shortcut.parts) } : {}) }], []);
    throw new Error(t("scheduleDialog.referenceUnavailable")); }, errorText: message });
const { open: pickerOpen, busy: pickerBusy, error: pickerError } = informationPicker;
async function continueContent(item: ShortcutSnapshot) {
  if (busy.value || !validContext.value || step.value !== "content") throw new Error(t("shortcuts.scopeChanged"));
  title.value = item.title; parts.value = informationComposerParts(item.parts?.length ? item.parts : [{ type: "text", text: item.content }], []);
  step.value = "timing";
}
function contentClosed(open: boolean) { if (!open && step.value === "content") emit("update:modelValue", false); }
function backToContent() { if (!busy.value && validContext.value) step.value = "content"; }
function toggleDay(day: number) { timing.value.weekdays = timing.value.weekdays.includes(day) ? timing.value.weekdays.filter(value => value !== day) : [...timing.value.weekdays, day]; }
function setExpiry(days: number) { neverExpires.value = false; expires.value = localDateTimeInput(new Date(Date.now() + days * 86400000).toISOString(), timing.value.timezone || props.serverTimezone || browserTimeZone()); }
async function confirmLeave() { if (busy.value || pickerBusy.value) return false; if (step.value === "content" && contentEditor.value) return await contentEditor.value.confirmLeave(); if (!dirty.value) return true; return await confirm.value?.ask({ title: t("scheduleDialog.discardTitle"), body: t("scheduleDialog.discardBody"), confirmText: t("scheduleDialog.discard"), cancelText: t("scheduleDialog.keepEditing"), danger: true }) ?? false; }
async function close() { if (await confirmLeave()) emit("update:modelValue", false); }
function hasWorkspaceFiles(input: readonly MessageInputPart[]): boolean { return input.some(part => part.type === "file" && !part.path.startsWith("information-assets/") || part.type === "shortcut" && part.parts && hasWorkspaceFiles(part.parts)); }
function buildBody(): ScheduleJobCreate {
  if (!title.value.trim()) throw new Error("scheduleDialog.titleRequired"); if (!targetAgent.value || targetAgent.value !== props.agentId) throw new Error("scheduleDialog.agentRequired");
  if (!inputPartsText(wireParts.value).trim()) throw new Error("scheduleDialog.instructionsRequired");
  if (turnLimitMode.value === "limited" && (!Number.isSafeInteger(maxTurns.value) || maxTurns.value < 1)) throw new Error("scheduleDialog.turnsInvalid");
  const wire = wireParts.value; if (validateInputParts(wire)) throw new Error("scheduleDialog.referencesInvalid");
  if (hasWorkspaceFiles(wire) && !sourceSession.value) throw new Error("nestedShortcuts.sessionRequired");
  const fallbackZone = props.item?.effective_timezone || props.serverTimezone || browserTimeZone(); const unchangedInstant = props.item && timing.value.frequency === "once" && timing.value.at === originalAtInput && timing.value.timezone === originalZone && originalAt;
  const payload = unchangedInstant ? { kind: "at" as const, at: originalAt, timezone: timing.value.timezone } : timingPayload(timing.value, fallbackZone);
  if (props.item && !timing.value.timezone && !props.item.effective_timezone && !props.serverTimezone && timing.value.frequency === "once" && timing.value.at !== originalAtInput) throw new Error("scheduleDialog.explicitZoneRequired");
  let expiry = ""; if (!neverExpires.value) { if (!expires.value) throw new Error("scheduleDialog.expiryRequired"); expiry = expires.value === originalExpiryInput && timing.value.timezone === originalZone && originalExpiry ? originalExpiry : dateTimeInputToISO(expires.value, timing.value.timezone || fallbackZone); if (new Date(expiry).getTime() <= Date.now()) throw new Error("scheduleDialog.expiryPast"); }
  return { title: title.value.trim(), agent_id: targetAgent.value, prompt: composerTypedText(parts.value) || inputPartsText(wire), parts: wire, input_layout: props.item?.input_layout || props.draft?.input_layout || "inline", ...((!props.item || hasWorkspaceFiles(wire)) && sourceSession.value ? { source_session_id: sourceSession.value } : {}), ...payload, turn_limit_mode: turnLimitMode.value, max_turns: turnLimitMode.value === "limited" ? maxTurns.value : turnLimitMode.value === "legacy" ? props.item?.max_turns || 0 : 0, approval_mode: approvalMode.value, expires_at: expiry };
}
function previewPayload() { const unchangedInstant = props.item && timing.value.frequency === "once" && timing.value.at === originalAtInput && timing.value.timezone === originalZone && originalAt; return unchangedInstant ? { kind: "at" as const, at: originalAt, timezone: timing.value.timezone } : timingPayload(timing.value, props.item?.effective_timezone || props.serverTimezone || browserTimeZone()); }
async function loadPreview() {
  clearTimeout(previewTimer); if (!props.modelValue || step.value !== "timing" || !validContext.value) return;
  const ticket = ++previewSequence, openedEpoch = epoch; let payload: ReturnType<typeof previewPayload>; nextRuns.value = []; previewError.value = ""; previewSignature.value = "";
  try { payload = previewPayload(); } catch (value) { previewError.value = message(value); previewLoading.value = false; return; }
  const signature = JSON.stringify(payload); previewLoading.value = true;
  try { const result = await api.schedulePreview(payload); if (disposed || ticket !== previewSequence || openedEpoch !== epoch || !props.modelValue || step.value !== "timing" || signature !== JSON.stringify(previewPayload())) return;
    nextRuns.value = result.next_runs || []; previewTimezone.value = result.timezone; previewSignature.value = signature; if (!nextRuns.value.length) previewError.value = t("scheduleDialog.noUpcomingRuns");
  } catch (value) { if (!disposed && ticket === previewSequence && openedEpoch === epoch) { previewError.value = message(value); nextRuns.value = []; previewSignature.value = ""; } }
  finally { if (!disposed && ticket === previewSequence && openedEpoch === epoch) previewLoading.value = false; }
}
watch(() => [props.modelValue, step.value, timing.value] as const, () => { clearTimeout(previewTimer); previewSequence++; previewSignature.value = ""; nextRuns.value = []; previewError.value = "";
  if (props.modelValue && step.value === "timing") { previewLoading.value = true; previewTimer = setTimeout(() => void loadPreview(), 300); } else previewLoading.value = false;
}, { deep: true, immediate: true });
const previewReady = computed(() => { try { return !!nextRuns.value.length && previewSignature.value === JSON.stringify(previewPayload()) && !previewLoading.value && !previewError.value; } catch { return false; } });
const previewDate = (iso: string) => scheduleDate(iso, timing.value.timezone || previewTimezone.value || props.item?.effective_timezone || props.serverTimezone || undefined, locale.value);
const planError = computed(() => { try { buildBody(); return ""; } catch (value) { return message(value); } });
async function save() {
  if (step.value !== "timing" || busy.value || !validContext.value || !previewReady.value) return;
  try { buildBody(); } catch (value) { error.value = message(value); return; } const ticket = epoch, currentContext = context(); saving.value = true; error.value = "";
  try { const frozenParts = await snapshotComposerElementIcons(parts.value); if (disposed || ticket !== epoch || currentContext !== context() || !props.modelValue) return; parts.value = frozenParts;
    const body = buildBody(); const result = props.item ? await api.scheduleUpdateJob(props.item.id, { ...body, revision: props.item.revision || 0 }) : await api.scheduleCreateJob(body);
    if (disposed || ticket !== epoch || currentContext !== context() || !props.modelValue) return; initial = state(); emit("saved", result.job); emit("update:modelValue", false);
  } catch (value) { if (!disposed && ticket === epoch) error.value = message(value); } finally { if (!disposed && ticket === epoch) saving.value = false; }
}
function keydown(event: KeyboardEvent) { if (event.defaultPrevented) return; if ((event.metaKey || event.ctrlKey) && event.key === "Enter") { event.preventDefault(); void save(); } if (event.key === "Escape") { event.preventDefault(); void close(); } }
