function beforeUnload(event: BeforeUnloadEvent) { if (dirty.value || saving.value) { event.preventDefault(); event.returnValue = ""; } }
if (typeof window !== "undefined") window.addEventListener("beforeunload", beforeUnload);
onBeforeUnmount(() => { disposed = true; epoch++; catalogSequence++; previewSequence++; clearTimeout(previewTimer); unregister(); if (typeof window !== "undefined") window.removeEventListener("beforeunload", beforeUnload); });
defineExpose({ confirmLeave, busy, dirty });
</script>
<template>
  <ShortcutEditorDialog ref="contentEditor" :model-value="modelValue && step === 'content'" purpose="schedule" :external-dirty="dirty" :item="contentItem" :scope-key="agentId" :session-id="sourceSession || sessionId" :library="catalog?.shortcuts || []" :reference-choices="referenceChoices" :resolve-reference="resolveReference" :skills="skills" :disabled="busy || !validContext" :save="continueContent" :upload-file="uploadFile" :pick-information="informationPicker.choose" @update:model-value="contentClosed">
    <template #context><section class="plan-agent"><div class="plan-agent-icon">{{ currentAgentName.slice(0, 1) || 'A' }}</div><div><small>{{ t('scheduleDialog.runBy') }}</small><strong>{{ currentAgentName || t('scheduleDialog.agentRequired') }}</strong><span>{{ t('scheduleDialog.followsAgent') }}<template v-if="currentModel"> · {{ currentModel }}</template></span></div><span class="plan-step-pill">{{ t('scheduleDialog.stepContentLabel') }}</span></section><p v-if="catalogError" class="plan-error" role="alert">{{ catalogError }} <button type="button" class="plan-text" @click="loadSources">{{ t('scheduleDialog.retry') }}</button></p><p v-else-if="catalogLoading" class="plan-note">{{ t('scheduleDialog.loadingSources') }}</p></template>
  </ShortcutEditorDialog>
  <el-dialog :model-value="modelValue && step === 'timing'" fullscreen append-to-body :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false" class="schedule-editor-dialog" data-testid="schedule-timing-editor" :before-close="close">
    <template #header><header class="plan-editor-header"><button type="button" class="plan-icon" :disabled="busy" :aria-label="t('scheduleDialog.backToContent')" data-testid="schedule-content-back" @click="backToContent"><el-icon><ArrowLeft /></el-icon></button><div><small>{{ t('scheduleDialog.stepTimingLabel') }}</small><h2>{{ t('scheduleDialog.stepTimingTitle') }}</h2></div><span v-if="dirty" class="plan-dirty">{{ t('scheduleDialog.unsaved') }}</span><button type="button" class="plan-secondary" :disabled="busy" data-testid="schedule-editor-back" @click="close">{{ t('scheduleDialog.cancel') }}</button><button type="button" class="plan-primary" :disabled="busy || !!planError || !validContext || !previewReady" data-testid="schedule-save" @click="save">{{ t(saving ? 'scheduleDialog.saving' : item ? 'scheduleDialog.saveChanges' : 'scheduleDialog.enablePlan') }}</button></header></template>
    <form class="plan-editor-layout" @submit.prevent="save" @keydown="keydown"><main class="plan-main"><div class="plan-section-head"><div><small class="plan-note">{{ t('scheduleDialog.contentReview') }}</small><h2 class="plan-task-title">{{ title }}</h2></div><button type="button" class="plan-secondary" :disabled="busy" @click="backToContent">{{ t('scheduleDialog.editContent') }}</button></div><section class="plan-agent"><div class="plan-agent-icon">{{ currentAgentName.slice(0, 1) || 'A' }}</div><div><small>{{ t('scheduleDialog.runBy') }}</small><strong>{{ currentAgentName }}</strong><span>{{ t('scheduleDialog.followsAgent') }}<template v-if="currentModel"> · {{ currentModel }}</template></span></div></section><div class="plan-content-preview" data-testid="schedule-content-review"><ShortcutContent :parts="wireParts" :content="composerTypedText(parts)" /></div><p class="plan-note plan-review-note">{{ t('scheduleDialog.referenceSnapshot') }}</p></main>
    <aside class="plan-settings"><section><div class="plan-section-head"><h3><el-icon><Clock /></el-icon>{{ t('scheduleDialog.when') }}</h3></div><label class="plan-field"><span>{{ t('scheduleDialog.frequency') }}</span><select v-model="timing.frequency" :disabled="busy" data-testid="schedule-frequency"><option v-for="frequency in frequencies" :key="frequency" :value="frequency">{{ t(`scheduleDialog.frequency_${frequency}`) }}</option></select></label><label v-if="timing.frequency === 'once'" class="plan-field"><span>{{ t('scheduleDialog.dateTime') }}</span><input v-model="timing.at" type="datetime-local" :disabled="busy" data-testid="schedule-at" /></label><label v-else-if="timing.frequency === 'hourly'" class="plan-field"><span>{{ t('scheduleDialog.minuteOfHour') }}</span><input v-model.number="timing.minute" type="number" min="0" max="59" :disabled="busy" data-testid="schedule-minute" /></label><div v-else-if="timing.frequency === 'interval'" class="plan-field"><span>{{ t('scheduleDialog.interval') }}</span><div class="plan-inline-fields"><input v-model.number="timing.every" type="number" min="1" :disabled="busy" data-testid="schedule-every" /><select v-model="timing.unit" :disabled="busy"><option value="minutes">{{ t('scheduleDialog.minutes') }}</option><option value="hours">{{ t('scheduleDialog.hours') }}</option><option value="days">{{ t('scheduleDialog.days') }}</option></select></div></div><label v-else-if="timing.frequency === 'custom'" class="plan-field"><span>{{ t('scheduleDialog.cronLabel') }}</span><input v-model="timing.cron" :disabled="busy" spellcheck="false" placeholder="0 9 * * *" data-testid="schedule-cron" /><small>{{ t('scheduleDialog.customHint') }}</small></label><label v-else class="plan-field"><span>{{ t('scheduleDialog.time') }}</span><input v-model="timing.time" type="time" :disabled="busy" data-testid="schedule-time" /></label><div v-if="timing.frequency === 'weekly'" class="plan-field"><span>{{ t('scheduleDialog.weekdays') }}</span><div 