      <section><h3>{{ t('scheduleDialog.validUntil') }}</h3><label class="plan-check"><input v-model="neverExpires" type="checkbox" :disabled="busy" data-testid="schedule-never-expires" />{{ t('scheduleDialog.neverExpires') }}</label><template v-if="!neverExpires"><input v-model="expires" type="datetime-local" :disabled="busy" class="plan-expiry" data-testid="schedule-expires" /><div class="plan-expiry-shortcuts"><button v-for="days in [7,30,90]" :key="days" type="button" :disabled="busy" @click="setExpiry(days)">{{ t('scheduleDialog.expireDays', { n: days }) }}</button></div></template></section><section><button type="button" class="plan-advanced" :aria-expanded="advanced" @click="advanced = !advanced">{{ t('scheduleDialog.advanced') }} <span>{{ advanced ? '−' : '+' }}</span></button><div v-if="advanced"><div class="plan-field"><span>{{ t('scheduleDialog.turnLimit') }}</span><select v-model="turnLimitMode" :disabled="busy" data-testid="schedule-turn-limit-mode"><option value="unlimited">{{ t('scheduleDialog.unlimitedTurns') }}</option><option value="limited">{{ t('scheduleDialog.customTurns') }}</option><option v-if="item && (!item.turn_limit_mode || item.turn_limit_mode === 'legacy')" value="legacy">{{ t('scheduleDialog.legacyTurns') }}</option></select><input v-if="turnLimitMode === 'limited'" v-model.number="maxTurns" type="number" min="1" :disabled="busy" data-testid="schedule-turns" /><small>{{ t('scheduleDialog.turnsHint') }}</small></div><label class="plan-field"><span>{{ t('scheduleDialog.approvalLabel') }}</span><select v-model="approvalMode" :disabled="busy" data-testid="schedule-approval"><option v-for="mode in ['auto','standard','strict'] as const" :key="mode" :value="mode">{{ t(`scheduleDialog.approval_${mode}`) }}</option></select><small>{{ t('scheduleDialog.approvalHint') }}</small></label><p v-if="item && !item.enabled" class="plan-note">{{ t('scheduleDialog.staysPaused') }}</p></div></section><p class="plan-runtime">{{ t('scheduleDialog.serverRuntime') }}</p></aside></form>
